import{_ as i,o as e,c as a,a2 as E}from"./chunks/framework.BXzK3EA4.js";const r="/assets/%E6%9C%8D%E5%8A%A1%E9%9D%A2%E6%9D%BF%E9%87%8D%E7%BD%AE%E5%AF%86%E7%A0%811._3fhs8Oo.png",n="/assets/dcim%E9%87%8D%E7%BD%AE%E5%AF%86%E7%A0%81.DcOhL8AQ.png",s="data:image/png;base64,",p="/assets/rc%E5%AF%86%E7%A0%81%E9%87%8D%E7%BD%AE.DrqLM20c.png",d=JSON.parse('{"title":"服务面板密码重置","description":"","frontmatter":{"title":"服务面板密码重置"},"headers":[],"relativePath":"beginners-guide/technical-support/panel-password-reset.md","filePath":"beginners-guide/technical-support/panel-password-reset.md","lastUpdated":1794292918000}'),g={name:"beginners-guide/technical-support/panel-password-reset.md"};function o(l,t,R,c,A,I){return e(),a("div",null,[...t[0]||(t[0]=[E('<p>本文档用于指导 RakSmart 用户在会员中心完成 DCIM 服务面板与 RAK Cloud 服务面板的密码重置操作，确保用户能够安全、高效地管理面板访问权限。</p><hr><h3 id="dcim-服务面板密码重置" tabindex="-1">DCIM 服务面板密码重置 <a class="header-anchor" href="#dcim-服务面板密码重置" aria-label="Permalink to &quot;DCIM 服务面板密码重置&quot;">​</a></h3><p>DCIM 服务面板（Data Center Infrastructure Management Service Panel）是 RakSmart 为物理服务器用户提供的数据中心基础设施管理控制台，用于远程管理和监控物理服务器的硬件状态、网络配置及运维操作。本文主要介绍如何在 RakSmart 控制台重置 DCIM 服务面板密码。</p><ol><li><p>登录 <a href="https://billing.raksmart.com/whmcs/clientarea.php?language=chinese-cn" target="_blank" rel="noreferrer">RakSmart 控制台</a>。</p></li><li><p>在左侧导航栏中，单击<strong>技术支持</strong> -&gt; <strong>服务面板密码重置</strong>，进入<strong>服务面板密码重置</strong>页面。</p><p><img src="'+r+'" alt="服务面板重置密码1.png"></p></li><li><p>你可以通过以下两种方式完成 DCIM 服务面板密码重置。</p><p><img src="'+n+'" alt="dcim重置密码.png"></p><p>a. 方式一：在<strong>新密码</strong>输入框中，输入符合复杂度要求的新密码。</p><p>b. 方式二：单击<strong>新密码</strong>输入框右侧的刷新图标，系统将自动生成高强度随机密码。</p></li><li><p>单击<strong>重置密码</strong>。</p></li><li><p>系统提示如下信息即完成 DCIM 服务面板密码更新。</p><p><img src="'+s+'" alt="重置密码成功.png"></p></li></ol><hr><h3 id="rak-cloud-服务面板密码重置" tabindex="-1">RAK Cloud 服务面板密码重置 <a class="header-anchor" href="#rak-cloud-服务面板密码重置" aria-label="Permalink to &quot;RAK Cloud 服务面板密码重置&quot;">​</a></h3><p>RAK Cloud 服务面板是 RakSmart 为云服务器用户提供的云资源管理控制台，用于自助管理/监控 云服务器、云存储、云网络等弹性云资源，支持系统重装、网络配置、快照管理等云服务全生命周期操作。本文主要介绍如何在 RakSmart 控制台重置 RAK Cloud 服务面板密码。</p><ol><li><p>登录 <a href="https://billing.raksmart.com/whmcs/clientarea.php?language=chinese-cn" target="_blank" rel="noreferrer">RakSmart 控制台</a>。</p></li><li><p>在左侧导航栏中，单击<strong>技术支持</strong> -&gt; <strong>服务面板密码重置</strong>，进入<strong>服务面板密码重置</strong>页面。</p><p><img src="'+r+'" alt="服务面板重置密码1.png"></p></li><li><p>你可以通过以下两种方式完成 RAK Cloud 服务面板密码重置。</p><p><img src="'+p+'" alt="rc密码重置.png"></p><p>a. 方式一：在<strong>新密码</strong>输入框中，输入符合复杂度要求的新密码。 b. 方式二：单击<strong>新密码</strong>输入框右侧的刷新图标，系统将自动生成高强度随机密码。</p></li><li><p>单击<strong>重置密码</strong>。</p></li><li><p>系统提示如下信息即完成 RAK Cloud 服务面板密码更新。</p><p><img src="'+s+'" alt="重置密码成功.png"></p></li></ol>',9)])])}const C=i(g,[["render",o]]);export{d as __pageData,C as default};
